2	    Core logic for the GitHub Actions environment matrix generator.
3	
4	    This file only defines functions -- dot-sourcing it has no side effects,
5	    which keeps it safe to load from both the CLI script and the Pester
6	    test suite. All GitHub Actions -related semantics implemented here
7	    (cartesian expansion, include/exclude merging, fail-fast/max-parallel
8	    passthrough) intentionally mirror the real strategy.matrix behavior
9	    documented for GitHub Actions.
10	#>
11	
12	# Normalizes a value (string, number, boolean, $null) to a string so that
13	# exclude/include rule matching works the same regardless of whether a JSON
14	# author wrote a bare number or a quoted string for something like a version.
15	function ConvertTo-ComparableString {
16	    param(
17	        [Parameter()]
18	        $Value
19	    )
20	    if ($null -eq $Value) { return '' }
21	    return [string]$Value
22	}
23	
24	# Builds the cartesian product of a set of named matrix dimensions.
25	# $Dimensions is an ordered dictionary: dimension name -> array of values.
26	# Returns a list of ordered hashtables (one per combination), each preserving
27	# the dimension key order so JSON output is deterministic.
28	function Get-MatrixCombinations {
29	    param(
30	        [Parameter(Mandatory)]
31	        [System.Collections.Specialized.OrderedDictionary]$Dimensions
32	    )
33	
34	    $combinations = [System.Collections.Generic.List[object]]::new()
35	    $combinations.Add([ordered]@{})
36	
37	    foreach ($key in $Dimensions.Keys) {
38	        $values = @($Dimensions[$key])
39	        $next = [System.Collections.Generic.List[object]]::new()
40	
41	        foreach ($combo in $combinations) {
42	            foreach ($value in $values) {
43	                $newCombo = [ordered]@{}
44	                foreach ($existingKey in $combo.Keys) {
45	                    $newCombo[$existingKey] = $combo[$existingKey]
46	                }
47	                $newCombo[$key] = $value
48	                $next.Add($newCombo)
49	            }
50	        }
51	
52	        $combinations = $next
53	    }
54	
55	    # Comma-prefix prevents PowerShell from unrolling the list on return,
56	    # which would otherwise collapse a single-item result to a scalar.
57	    return , $combinations
58	}
59	
60	# An exclude rule matches a combination when every key named in the rule
61	# has an equal value in the combination. Keys the rule does not mention are
62	# ignored (wildcarded), matching GitHub Actions' documented exclude behavior.
63	function Test-ExcludeMatch {
64	    param(
65	        [Parameter(Mandatory)] $Combination,
66	        [Parameter(Mandatory)] $ExcludeRule
67	    )
68	
69	    foreach ($key in $ExcludeRule.PSObject.Properties.Name) {
70	        if (-not $Combination.Contains($key)) { return $false }
71	        $comboValue = ConvertTo-ComparableString $Combination[$key]
72	        $ruleValue = ConvertTo-ComparableString $ExcludeRule.$key
73	        if ($comboValue -ne $ruleValue) { return $false }
74	    }
75	    return $true
76	}
77	
78	# Removes every combination matched by at least one exclude rule.
79	function Remove-ExcludedCombinations {
80	    param(
81	        [Parameter(Mandatory)] [AllowEmptyCollection()] $Combinations,
82	        [AllowEmptyCollection()] $ExcludeRules = @()
83	    )
84	
85	    $rules = @($ExcludeRules)
86	    $result = [System.Collections.Generic.List[object]]::new()
87	
88	    foreach ($combo in $Combinations) {
89	        $excluded = $false
90	        foreach ($rule in $rules) {
91	            if (Test-ExcludeMatch -Combination $combo -ExcludeRule $rule) {
92	                $excluded = $true
93	                break
94	            }
95	        }
96	        if (-not $excluded) { $result.Add($combo) }
97	    }
98	
99	    return , $result
100	}
101	
102	# An include rule "matches" an existing combination when every one of the
103	# rule's properties that IS a declared matrix dimension key has an equal
104	# value in that combination. Properties the rule does not mention are
105	# wildcarded. A rule with no dimension-key overlap never matches anything.
106	function Test-IncludeDimensionMatch {
107	    param(
108	        [Parameter(Mandatory)] $Combination,
109	        [Parameter(Mandatory)] $IncludeRule,
110	        [Parameter(Mandatory)] [string[]]$DimensionKeys
111	    )
112	
113	    $ruleKeys = @($IncludeRule.PSObject.Properties.Name) | Where-Object { $DimensionKeys -contains $_ }
114	    if (@($ruleKeys).Count -eq 0) { return $false }
115	
116	    foreach ($key in $ruleKeys) {
117	        $comboValue = ConvertTo-ComparableString $Combination[$key]
118	        $ruleValue = ConvertTo-ComparableString $IncludeRule.$key
119	        if ($comboValue -ne $ruleValue) { return $false }
120	    }
121	    return $true
122	}
123	
124	# Applies GitHub Actions' include semantics:
125	#   - if an include rule matches one or more existing combinations (on the
126	#     dimension keys it specifies), its extra properties are merged into
127	#     every one of those combinations;
128	#   - otherwise the rule is appended as a brand-new combination, using
129	#     exactly the properties it specifies.
130	function Merge-IncludeRules {
131	    param(
132	        [Parameter(Mandatory)] [AllowEmptyCollection()] $Combinations,
133	        [AllowEmptyCollection()] $IncludeRules = @(),
134	        [Parameter(Mandatory)] [string[]]$DimensionKeys
135	    )
136	
137	    $result = [System.Collections.Generic.List[object]]::new()
138	    foreach ($combo in $Combinations) { $result.Add($combo) }
139	
140	    foreach ($rule in @($IncludeRules)) {
141	        $matched = $false
142	
143	        for ($i = 0; $i -lt $result.Count; $i++) {
144	            if (Test-IncludeDimensionMatch -Combination $result[$i] -IncludeRule $rule -DimensionKeys $DimensionKeys) {
145	                $matched = $true
146	                foreach ($propName in $rule.PSObject.Properties.Name) {
147	                    $result[$i][$propName] = $rule.$propName
148	                }
149	            }
150	        }
151	
152	        if (-not $matched) {
153	            $newCombo = [ordered]@{}
154	            foreach ($propName in $rule.PSObject.Properties.Name) {
155	                $newCombo[$propName] = $rule.$propName
156	            }
157	            $result.Add($newCombo)
158	        }
159	    }
160	
161	    return , $result
162	}
163	
164	# Orchestrates the full pipeline: validate config, expand the cartesian
165	# matrix, apply exclude/include rules, validate the resulting size, and
166	# assemble the strategy.matrix-shaped output object.
167	function New-BuildMatrix {
168	    param(
169	        [Parameter(Mandatory)] $Config,
170	        [Nullable[int]]$MaxMatrixSizeOverride
171	    )
172	
173	    if ($null -eq $Config -or -not ($Config.PSObject.Properties.Name -contains 'matrix') -or $null -eq $Config.matrix) {
174	        throw "Configuration must include a non-empty 'matrix' object defining at least one dimension."
175	    }
176	
177	    $dimensionNames = @($Config.matrix.PSObject.Properties.Name)
178	    if ($dimensionNames.Count -eq 0) {
179	        throw "Configuration must include a non-empty 'matrix' object defining at least one dimension."
180	    }
181	
182	    $dimensions = [ordered]@{}
183	    foreach ($name in $dimensionNames) {
184	        $values = @($Config.matrix.$name)
185	        if ($values.Count -eq 0) {
186	            throw "Matrix dimension '$name' must contain at least one value."
187	        }
188	        $dimensions[$name] = $values
189	    }
190	
191	    $combinations = Get-MatrixCombinations -Dimensions $dimensions
192	
193	    $excludeRules = @()
194	    if ($Config.PSObject.Properties.Name -contains 'exclude' -and $Config.exclude) {
195	        $excludeRules = @($Config.exclude)
196	    }
197	    $combinations = Remove-ExcludedCombinations -Combinations $combinations -ExcludeRules $excludeRules
198	
199	    $includeRules = @()
200	    if ($Config.PSObject.Properties.Name -contains 'include' -and $Config.include) {
201	        $includeRules = @($Config.include)
202	    }
203	    $combinations = Merge-IncludeRules -Combinations $combinations -IncludeRules $includeRules -DimensionKeys $dimensionNames
204	
205	    # Effective max matrix size, in increasing priority order:
206	    #   built-in default (256, GitHub Actions' own hard limit)
207	    #   < $env:MATRIX_MAX_SIZE < -MaxMatrixSizeOverride param < config's maxMatrixSize.
208	    $effectiveMax = 256
209	    if ($env:MATRIX_MAX_SIZE) { $effectiveMax = [int]$env:MATRIX_MAX_SIZE }
210	    if ($null -ne $MaxMatrixSizeOverride) { $effectiveMax = $MaxMatrixSizeOverride }
211	    if ($Config.PSObject.Properties.Name -contains 'maxMatrixSize' -and $Config.maxMatrixSize) {
212	        $effectiveMax = [int]$Config.maxMatrixSize
213	    }
214	
215	    if ($combinations.Count -gt $effectiveMax) {
216	        throw "Generated matrix contains $($combinations.Count) combination(s), exceeding the maximum allowed size of $effectiveMax. Reduce matrix dimensions or add exclude rules."
217	    }
218	
219	    $failFast = $true
220	    if ($Config.PSObject.Properties.Name -contains 'failFast' -and $null -ne $Config.failFast) {
221	        if ($Config.failFast -isnot [bool]) {
222	            throw "The 'failFast' setting must be a boolean (true or false)."
223	        }
224	        $failFast = $Config.failFast
225	    }
226	
227	    $strategy = [ordered]@{
228	        'fail-fast' = $failFast
229	        'matrix'    = [ordered]@{
230	            'include' = $combinations
231	        }
232	    }
233	
234	    if ($Config.PSObject.Properties.Name -contains 'maxParallel' -and $null -ne $Config.maxParallel) {
235	        $maxParallel = 0
236	        if (-not [int]::TryParse([string]$Config.maxParallel, [ref]$maxParallel) -or $maxParallel -le 0) {
237	            throw "The 'maxParallel' setting must be a positive integer."
238	        }
239	        $strategy['max-parallel'] = $maxParallel
240	    }
241	
242	    return [ordered]@{ 'strategy' = $strategy }
243	}
